    # using a 'Buy it Now' option. <br><br> <b>For GetOrders and GetItemTransactions only:</b>
    order_line_item_id: str | None = Field(None, alias="OrderLineItemID")

    # The generated eBay payment ID used by the buyer when he/she chooses electronic transfer as
    # payment method for paying the seller. This field is only applicable to the eBay Germany
    # site (Site ID 77).
    e_bay_payment_id: str | None = Field(None, alias="eBayPaymentID")

    # A container consisting of name and ID of the seller's discount campaign, as well as the
    # discount amount that is being applied to the order line item. This container is only
    # returned if the order line item is eligible for seller discounts.
    seller_discounts: SellerDiscountsType | None = Field(None, alias="SellerDiscounts")

    # This field is returned if the <b>IncludeCodiceFiscale</b> flag is included in the request
    # and set to <code>true</code>, and if the buyer has provided this value at checkout time.
    # <br/><br/> This field is only applicable to buyers on the Italy and Spain sites. The
    codice_fiscale: str | None = Field(None, alias="CodiceFiscale")

    # Order line items requiring multiple shipping legs include items being shipped through the
    # Global Shipping Program or through eBay International Shipping, as well as order line
    # items subject to/eligible for the Authenticity Guarantee program. For both international
    is_multi_leg_shipping: bool | None = Field(None, alias="IsMultiLegShipping")

    # This container consists of details related to the first leg of an order requiring multiple
    # shipping legs. Types of orders that require multiple shipping legs include international
    # orders going through the Global Shipping Program or through eBay International Shipping,
    multi_leg_shipping_details: MultiLegShippingDetailsType | None = Field(
        None, alias="MultiLegShippingDetails"
    )

    # This field indicates the date/time that an order invoice was sent from the seller to the
    # buyer. This field is only returned if an invoice (containing the order line item) was sent
    # to the buyer.
    invoice_sent_time: str | None = Field(None, alias="InvoiceSentTime")

    # This flag indicates whether or not the order line item is an intangible good, such as an
    # MP3 track or a mobile phone ringtone.
    intangible_item: bool | None = Field(None, alias="IntangibleItem")

    # Contains information about each monetary transaction that occurs for the order line item,
    # including order payment, any refund, a credit, etc. Both the payer and payee are shown in
    # this container.
    monetary_details: PaymentsInformationType | None = Field(None, alias="MonetaryDetails")

    # Container consisting of an array of <strong>PickupOptions</strong> containers. Each
    # <strong>PickupOptions</strong> container consists of the pickup method and its priority.
    # The priority of each pickup method controls the order (relative to other pickup methods)
    pickup_details: PickupDetailsType | None = Field(None, alias="PickupDetails")

    # <span class="tablenote"><b>Note: </b> Since BOPIS (Buy Online, Pick Up In Store) is no
    # longer available, this container and its associated fields are no longer available for
    # active use in the Trading API. </span>
    pickup_method_selected: PickupMethodSelectedType | None = Field(
        None, alias="PickupMethodSelected"
    )

    # This field will be returned at the order line item level only if the buyer purchased a
    # digital gift card, which is delivered by email, or if the buyer purchased an item that is
    # enabled with the 'Click and Collect' feature. <br/><br/> Currently,
    logistics_plan_type: str | None = Field(None, alias="LogisticsPlanType")

    # This container is returned in <b>GetOrders</b> (and other order management calls) if the
    # 'Pay Upon Invoice' option is being offered to the buyer, and the seller is including
    # payment instructions in the shipping package(s) for the order. The 'Pay Upon Invoice'
    buyer_package_enclosures: BuyerPackageEnclosuresType | None = Field(
        None, alias="BuyerPackageEnclosures"
    )

    # The unique identifier of the inventory reservation.
    inventory_reservation_id: str | None = Field(None, alias="InventoryReservationID")

    # A unique identifier for an eBay order. This field is only returned for paid orders, and
    # not unpaid orders. <br> <span class="tablenote"><b>Note: </b> <b>ExtendedOrderID</b> was
    # first created when eBay changed the format of Order IDs back in June 2019. For a short
    extended_order_id: str | None = Field(None, alias="ExtendedOrderID")

    # If <code>true</code>, the buyer of the order line item has an eBay Plus subscription and
    # is eligible to receive program benefits, such as fast, free domestic shipping and free
    # returns on eligible items. eBay determines which listings qualify for eBay Plus based on
    e_bay_plus_transaction: bool | None = Field(None, alias="eBayPlusTransaction")

    # This container is returned in <b>GetOrders</b> and other order management calls if a buyer
    # has purchased a digital gift card but has sent it to another individual as a gift, and has
    # left a message for the recipient. The <b>GiftSummary</b> container consists of the message
    gift_summary: GiftSummaryType | None = Field(None, alias="GiftSummary")

    # This container is only returned by <b>GetOrders</b> and other order management calls if
    # the buyer purchased a digital gift card for themselves, or is giving the digital gift card
    # to someone else as a gift (in this case, the <b>Gift</b> boolean field will be returned
    digital_delivery_selected: DigitalDeliverySelectedType | None = Field(
        None, alias="DigitalDeliverySelected"
    )

    # This boolean field is returned as <code>true</code> if the seller is giving a digital gift
    # card to another individual as a gift. This field is only applicable for digital gift card
    # order line items.
    gift: bool | None = Field(None, alias="Gift")

    # <span class="tablenote"><b>Note: </b> This field is for future use, as the eBay Guaranteed
    # Shipping feature has been put on hold. eBay Guaranteed Shipping should not be confused
    # with eBay Guaranteed Delivery, which is a completely different feature. </span> This field
    guaranteed_shipping: bool | None = Field(None, alias="GuaranteedShipping")

    # This field is deprecated, and can be ignored if returned. The Guaranteed Delivery program
    # is no longer supported on any eBay marketplace.
    guaranteed_delivery: bool | None = Field(None, alias="GuaranteedDelivery")

    # This boolean field is returned as <code>true</code> if the line item is subject to a tax
    # (US sales tax or Australian Goods and Services tax) that eBay will collect and remit to
    # the proper taxing authority on the buyer's behalf. This field is also returned if
    e_bay_collect_and_remit_tax: bool | None = Field(None, alias="eBayCollectAndRemitTax")

    # This container is returned if the order line item is subject to a tax (US sales tax or
    # Australian Goods and Services tax) that eBay will collect and remit to the proper taxing
    # authority on the buyer's behalf. The type of tax will be shown in the
    e_bay_collect_and_remit_taxes: TaxesType | None = Field(None, alias="eBayCollectAndRemitTaxes")

    # This container gives the status of an order line item going through the Authenticity
    # Guarantee service process. In the Authenticity Guarantee service program, a third-party
    # authenticator must verify the authenticity of the item before it can be sent to the buyer.
    program: TransactionProgramType | None = Field(None, alias="Program")

    # <span class="tablenote"><b>Note: </b> This array is only returned if the order has
    # associated linked line items.</span> Container consisting of an array of linked line item
    # objects.
    linked_line_item_array: LinkedLineItemArrayType | None = Field(
        None, alias="LinkedLineItemArray"
    )
